 pub fn lock_for_export(&self,dir:&std::fs::File,id:&str,password:&str)->Result<(std::fs::File,std::fs::File),String>{
  if id!="default"&&!valid_id(id){return Err("Пространство недоступно".into())}if self.lookup(id).is_some(){return Err("Закройте защищённое пространство перед сохранением копии".into())}let lock=lock_workspace_fd(dir)?;if self.lookup(id).is_some(){return Err("Закройте защищённое пространство перед сохранением копии".into())}let source=Vault::verify_closed_dir(dir,password)?;Ok((lock,source))
 }
 pub fn rename(&self,root:&Path,default:&Path,id:&str,name:&str)->Result<Value,String>{let name=name.trim();if name.is_empty()||name.chars().count()>100{return Err("Неверное имя".into())}let entry=self.lookup(id).ok_or("Пространство заблокировано")?;let vault=entry.vault.lock().map_err(|_|"Пространство недоступно")?;let _gate=entry.commit_gate.lock().map_err(|_|"Пространство недоступно")?;if !entry.active.load(Ordering::Acquire){return Err("Пространство заблокировано".into())}vault.set_workspace_name(name)?;let dir=crate::workspace_paths::resolve(root,default,id);std::fs::write(dir.join(".workspace.json"),json!({"name":name,"protected":true}).to_string()).map_err(|_|"Не удалось сохранить название пространства")?;Ok(json!({"id":id,"name":name,"protected":true}))}
