  for required in [".atlas-protected",".workspace.json","workspace.atlas"] {if !names.iter().any(|x|x.as_bytes()==required.as_bytes()){return Err("Пространство не подтверждено".into())}}
  let marker=CString::new(".atlas-protected").unwrap();let fd=unsafe{libc::openat(dir.as_raw_fd(),marker.as_ptr(),libc::O_RDONLY|libc::O_NOFOLLOW|libc::O_CLOEXEC)};if fd<0{return Err("Пространство не подтверждено".into())}let mut marker=unsafe{std::fs::File::from_raw_fd(fd)};let mut value=String::new();marker.by_ref().take(128).read_to_string(&mut value).map_err(|_|"Пространство не подтверждено")?;if value!="atlas-protected-v1"{return Err("Пространство не подтверждено".into())}
