 pub fn delete(&self,_root:&Path,_id:&str,_dir_name:&str)->Result<(),String>{Err("Удаление на этой системе пока недоступно".into())}
 pub fn close(&self,id:&str){let entry=self.open.lock().ok().and_then(|mut open|open.remove(id));if let Some(entry)=entry{if let Ok(_gate)=entry.commit_gate.lock(){entry.active.store(false,Ordering::Release);}else{entry.active.store(false,Ordering::Release);}}self.invalidate(id);}
