 fn session(&self,id:&str)->Option<u64>{let entry=self.lookup(id)?;if entry.active.load(Ordering::Acquire){Some(entry.cookie)}else{None}}
 fn invalidate(&self,id:&str){if let Ok(mut cache)=self.fingerprints.lock(){cache.remove(id);}}
