 fn schedule(self:&Arc<Self>,id:&str,service:super::semantic::SemanticService,fingerprint:String,cookie:u64){let id=id.to_owned();let mut running=match self.running.lock(){Ok(v)=>v,Err(_)=>return};if !running.insert(id.clone()){return}drop(running);if let Ok(mut errors)=self.errors.lock(){errors.remove(&id);}let owner=Arc::clone(self);std::thread::spawn(move||{let previous=owner.lookup(&id).and_then(|entry|{if entry.cookie!=cookie||!entry.active.load(Ordering::Acquire){return None}let vault=entry.vault.lock().ok()?;vault.load_semantic().ok()});let mut cursor:Option<String>=None;let result=service.protected_build(||{let entry=owner.lookup(&id).ok_or("workspace unavailable")?;if entry.cookie!=cookie||!entry.active.load(Ordering::Acquire){return Err("indexing cancelled".into())}let vault=entry.vault.lock().map_err(|_|"workspace unavailable")?;if !entry.active.load(Ordering::Acquire){return Err("indexing cancelled".into())}let next=vault.semantic_source_after(cursor.as_deref())?;if let Some((ref source_id,_,_,_))=next{cursor=Some(source_id.clone());}Ok(next)},previous.as_ref().map(|(i,m)|(i,m)),||owner.session(&id)==Some(cookie));let mut failure=result.as_ref().err().map(|e|safe_semantic_error(e));if let Ok((bytes,mut metadata))=result {metadata["source_hash"]=json!(fingerprint);if let Some(entry)=owner.lookup(&id){if entry.cookie==cookie&&entry.active.load(Ordering::Acquire){if let Ok(mut vault)=entry.vault.lock(){if let Ok(_gate)=entry.commit_gate.lock(){if entry.active.load(Ordering::Acquire)&&owner.fingerprint(&id,&vault).ok().as_deref()==Some(&fingerprint){if vault.save_semantic(&bytes,&metadata).is_err(){failure=Some("Не удалось сохранить индекс".into());}}}}}}}if let Some(message)=failure {if owner.session(&id)==Some(cookie){if let Ok(mut errors)=owner.errors.lock(){errors.insert(id.clone(),(fingerprint,message));}}}if let Ok(mut r)=owner.running.lock(){r.remove(&id);}});}
 pub fn unlocked(&self,id:&str)->bool{self.open.lock().map(|o|o.contains_key(id)).unwrap_or(false)}
