fn lock_workspace_fd(dir:&std::fs::File)->Result<std::fs::File,String>{use std::os::fd::{AsRawFd,FromRawFd};let name=std::ffi::CString::new(".atlas-protected").unwrap();let fd=unsafe{libc::openat(dir.as_raw_fd(),name.as_ptr(),libc::O_RDWR|libc::O_NOFOLLOW|libc::O_CLOEXEC|libc::O_NONBLOCK)};if fd<0{return Err("Пространство недоступно".into())}let file=unsafe{std::fs::File::from_raw_fd(fd)};if !file.metadata().map_err(|_|"Пространство недоступно")?.is_file(){return Err("Пространство недоступно".into())}if unsafe{libc::flock(file.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)}!=0{return Err("Пространство уже открыто".into())}Ok(file)}
fn lock_workspace(dir:&Path)->Result<std::fs::File,String>{use std::os::unix::fs::OpenOptionsExt;if dir.is_symlink()||!dir.is_dir(){return Err("Пространство недоступно".into())}let file=std::fs::OpenOptions::new().read(true).write(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(dir.join(".atlas-protected")).map_err(|_|"Пространство недоступно")?;if !file.metadata().map_err(|_|"Пространство недоступно")?.is_file(){return Err("Пространство недоступно".into())}use std::os::fd::AsRawFd;if unsafe{libc::flock(file.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)}!=0{let error=std::io::Error::last_os_error();return if matches!(error.raw_os_error(),Some(libc::EWOULDBLOCK)){Err("Пространство уже открыто".into())}else{Err("Пространство недоступно".into())}}Ok(file)}
