pub(crate) fn parse_range(value:&str,size:u64)->Option<(u64,u64)>{if size==0{return None}let v=value.strip_prefix("bytes=")?;if v.contains(','){return None}let (a,b)=v.split_once('-')?;if a.is_empty(){let n=b.parse::<u64>().ok()?;if n==0{return None}return Some((size.saturating_sub(n),size))}let start=a.parse::<u64>().ok()?;if start>=size{return None}let end=if b.is_empty(){size}else{b.parse::<u64>().ok()?.checked_add(1)?.min(size)};if end<=start{return None}Some((start,end))}
struct ProtectedUpload<'a>{source:&'a mut dyn Read,remaining:u64,entry:&'a OpenVault}
impl Read for ProtectedUpload<'_>{fn read(&mut self,buf:&mut[u8])->io::Result<usize>{if !self.entry.active.load(Ordering::Acquire){return Err(io::Error::other("workspace locked"))}if self.remaining==0{return Ok(0)}let limit=buf.len().min(self.remaining as usize);let n=self.source.read(&mut buf[..limit])?;if !self.entry.active.load(Ordering::Acquire){return Err(io::Error::other("workspace locked"))}if n==0{return Err(io::Error::new(io::ErrorKind::UnexpectedEof,"incomplete upload"))}self.remaining-=n as u64;Ok(n)}}
struct ProtectedReader{entry:Arc<OpenVault>,file:String,position:u64,end:u64,first:bool}
impl Read for ProtectedReader{fn read(&mut self,buf:&mut[u8])->io::Result<usize>{if !self.entry.active.load(Ordering::Acquire){return Err(io::Error::other("workspace locked"))}if self.position>=self.end||buf.is_empty(){return Ok(0)}let amount=(self.end-self.position).min(buf.len() as u64).min(65536);let vault=self.entry.vault.lock().map_err(|_|io::Error::other("workspace unavailable"))?;if !self.entry.active.load(Ordering::Acquire){return Err(io::Error::other("workspace locked"))}let mut bytes=Vec::with_capacity(amount as usize);vault.read_range(&self.file,self.position,amount,&mut bytes).map_err(io::Error::other)?;if !self.entry.active.load(Ordering::Acquire){return Err(io::Error::other("workspace locked"))}if bytes.is_empty(){return Err(io::Error::new(io::ErrorKind::UnexpectedEof,"incomplete protected file"))}buf[..bytes.len()].copy_from_slice(&bytes);self.position+=bytes.len() as u64;drop(vault);if self.first{self.first=false;download_barrier();}Ok(bytes.len())}}

#[cfg(feature="test-hook")]
