fn download_barrier(){}
fn safe_semantic_error(error:&str)->String{for allowed in ["Текст одного объекта превышает предел 32 МиБ","Смысловой поиск ограничен 16 000 фрагментов","Метаданные смыслового поиска превышают 32 МиБ"]{if error==allowed{return allowed.to_owned()}}"Не удалось подготовить поиск".into()}
fn lexical_search(vault:&mut Vault,b:&Value)->Result<Value,String>{let query=b["query"].as_str().ok_or("Нет запроса")?;if b["mode"].as_str()!=Some("lexical"){return Err("Неверный режим".into())}let ids:Option<Vec<String>>=match b.get("object_ids"){None|Some(Value::Null)=>None,Some(Value::Array(items))=>Some(items.iter().map(|v|v.as_str().map(str::to_owned).ok_or("Неверный фильтр")).collect::<Result<_,_>>()?),_=>return Err("Неверный фильтр".into())};let results=vault.search_chunks(query,ids.as_deref(),128)?;let created_at=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_err(|_|"Неверное время")?.as_secs_f64();let saved=history_results(vault,&results)?;vault.record_history(json!({"query":query,"mode":"lexical","results":saved,"created_at":created_at,"object_ids":ids,"scope_known":true,"order_exact":true}))?;Ok(json!({"results":results}))}

fn select_rag(rows:&[Value],limit:usize,threshold:f64)->Vec<Value>{let mut out=Vec::new();let mut remaining=24000usize;for result in rows {if result["score"].as_f64().is_none_or(|score|!score.is_finite()||score<threshold){continue}let title=result["title"].as_str().unwrap_or("");for chunk in result["chunks"].as_array().into_iter().flatten(){let text=chunk["text"].as_str().unwrap_or("");let overhead=title.chars().take(150).collect::<String>().len()+40;if text.trim().is_empty()||remaining<=overhead+100{continue}remaining-=overhead;let mut end=text.len().min(remaining);while !text.is_char_boundary(end){end-=1}let excerpt=&text[..end];if excerpt.trim().is_empty(){continue}if let Some(start)=chunk["start"].as_u64(){out.push(json!({"id":result["id"],"title":title,"text":excerpt,"start":start,"end":start+excerpt.chars().count() as u64,"field":chunk["field"]}));remaining-=end;}if out.len()>=limit{return out}}}out}
fn protected_rag(service:&super::semantic::SemanticService,index:&atlas_faiss_probe::Index,metadata:&Value,query:&str,ids:Option<&[String]>,mut results:Vec<Value>,agentic:bool,rag:&Arc<Mutex<super::RagState>>)->Result<(Vec<Value>,Option<String>,Vec<Value>,Option<String>),String>{let generator={let guard=rag.lock().map_err(|_|"model unavailable")?;match &*guard{super::RagState::Ready(g)=>Some(g.clone()),_=>None}};let mut answer=None;let mut sources=Vec::new();let mut error=None;let mut candidates=results.clone();if let Some(generator)=generator{let generator=generator.acquire()?;
 if !agentic{let first=select_rag(&candidates,5,0.70);if !first.is_empty(){let generated=generator.answer(query,&first);if !super::accept_answer(&mut answer,&mut sources,first,generated){error=Some("Не удалось сформировать ответ. Найденные фрагменты доступны ниже.".into())}}}
 let mut retry=agentic||sources.is_empty();if !retry {if let Some(a)=answer.as_ref(){retry=match generator.answer_quality(query,a,&sources){Ok(v)=>v!="sufficient",Err(_)=>{error=Some("Не удалось проверить полноту ответа".into());false}}}}
 if retry&&!agentic{let expanded=select_rag(&candidates,8,0.65);if expanded.len()>sources.len(){let generated=generator.answer(query,&expanded);if super::accept_answer(&mut answer,&mut sources,expanded,generated){if let Some(a)=answer.as_ref(){retry=match generator.answer_quality(query,a,&sources){Ok(v)=>v!="sufficient",Err(_)=>{error=Some("Не удалось проверить полноту ответа".into());false}}}}else{error=Some("Не удалось расширить ответ; показан предыдущий результат".into());retry=false}}}
 if retry{let questions=if error.is_some(){Vec::new()}else{match generator.search_questions(query,agentic){Ok(v)=>v,Err(_)=>{error=Some("Не удалось подготовить дополнительные поисковые запросы".into());Vec::new()}}};let mut groups=Vec::new();for q in questions.iter().take(if agentic{3}else{2}){let more=match service.protected_search(index,metadata,q,ids){Ok(v)=>v,Err(_)=>{error=Some("Не удалось выполнить дополнительный поиск".into());break}};groups.push(more.into_iter().filter(|r|r["score"].as_f64().is_some_and(|v|v.is_finite()&&v>=0.65)).take(4).collect::<Vec<_>>());}candidates=super::merge_agentic(&groups,candidates);let mut visible=std::collections::HashSet::new();for r in &results{for c in r["chunks"].as_array().into_iter().flatten(){visible.insert((r["id"].to_string(),c["field"].to_string(),c["start"].to_string(),c["end"].to_string()));}}let original=results.len();for r in &candidates{if results.len()>=original+12{break}let fresh=r["chunks"].as_array().is_some_and(|chunks|chunks.iter().any(|c|visible.insert((r["id"].to_string(),c["field"].to_string(),c["start"].to_string(),c["end"].to_string()))));if fresh{results.push(r.clone())}}let proposed=select_rag(&candidates,8,0.65);if !proposed.is_empty()&&error.is_none(){let generated=generator.answer(query,&proposed);if !super::accept_answer(&mut answer,&mut sources,proposed,generated){error=Some("Не удалось улучшить ответ; показан предыдущий результат".into())}else if let Some(a)=answer.as_ref(){match generator.answer_quality(query,a,&sources){Ok(v) if v!="sufficient"=>error=Some("Ответ может быть неполным: проверьте найденные фрагменты".into()),Err(_)=>error=Some("Не удалось проверить полноту ответа".into()),_=>{}}}}}
 if sources.is_empty()&&error.is_none(){answer=Some("Не найдено достаточно близких фрагментов".into())}}
 else if candidates.is_empty(){answer=Some("Не найдено достаточно близких фрагментов".into())}else{return Err("Модель ответа не загружена".into())}Ok((results,answer,sources,error))}

fn note_revision(id:&str,title:&str,text:&str)->String{use sha2::{Digest,Sha256};let fields=[id,"note",title,""];let prefix=format!("[{}]",fields.iter().map(|v|serde_json::to_string(v).unwrap()).collect::<Vec<_>>().join(", "));let mut hash=Sha256::new();hash.update(prefix.as_bytes());hash.update(text.as_bytes());format!("{:x}",hash.finalize())}
fn history_results(vault:&Vault,results:&[Value])->Result<Vec<Value>,String>{let mut saved=results.to_vec();for result in &mut saved{let id=result["id"].as_str().unwrap_or("");if let Some((title,body,description))=vault.history_source(id)?{result["_source_hash"]=json!(super::source_hash(&title,&body,&description));}}Ok(saved)}
fn span_matches(text:&str,start:Option<u64>,end:Option<u64>,expected:&str)->bool{let (Some(start),Some(end))=(start,end)else{return false};if end<start{return false}let Ok(start)=usize::try_from(start)else{return false};let Ok(length)=usize::try_from(end-start as u64)else{return false};let mut chars=text.chars();if start>0&&chars.nth(start-1).is_none(){return false}let actual:String=chars.take(length).collect();actual.chars().count()==length&&actual==expected}
fn enrich_history(vault:&Vault,mut entries:Vec<Value>)->Result<Vec<Value>,String>{for entry in &mut entries {if let Some(results)=entry["results"].as_array_mut(){for result in results {let id=result["id"].as_str().unwrap_or("");let current=vault.history_source(id)?;let saved=result.get("_source_hash").and_then(Value::as_str).map(str::to_owned);let stale=current.as_ref().is_none_or(|(t,b,d)|saved.as_deref()!=Some(super::source_hash(t,b,d).as_str())||result["title"].as_str()!=Some(t));if let Some(object)=result.as_object_mut(){object.remove("_source_hash");object.insert("missing".into(),json!(current.is_none()));object.insert("stale".into(),json!(stale));}if let Some(chunks)=result["chunks"].as_array_mut(){for chunk in chunks {let text=current.as_ref().map(|(_,body,desc)|if chunk["field"]=="description"{desc.as_str()}else{body.as_str()}).unwrap_or("");let matches=span_matches(text,chunk["start"].as_u64(),chunk["end"].as_u64(),chunk["text"].as_str().unwrap_or(""));chunk["stale"]=json!(stale||!matches);}}}}if let Some(sources)=entry["sources"].as_array_mut(){for source in sources {let id=source["id"].as_str().unwrap_or("");let current=vault.history_source(id)?;let text=current.as_ref().map(|(_,body,desc)|if source["field"]=="description"{desc.as_str()}else{body.as_str()}).unwrap_or("");let matches=span_matches(text,source["start"].as_u64(),source["end"].as_u64(),source["text"].as_str().unwrap_or(""));source["missing"]=json!(current.is_none());source["stale"]=json!(!matches);}}}Ok(entries)}
